public:
    int myAtoi(string s) {
        int i = 0, n = s.size();
        while (i < n && s[i] == ' ') i++;
        if (i == n) return 0;
        int sign = 1;
        if (s[i] == '-') {
            sign = -1; i++;
        } else if (s[i] == '+') {
            i++;
        }
        long long res = 0;
        while (i < n && isdigit(s[i])) {
            int digit = s[i] - '0';
            if (res > (INT_MAX - digit) / 10) {
                return sign == 1 ? INT_MAX : INT_MIN;
            }
            res = res * 10 + digit;
            i++;
        }
        return (int)(sign * res);
    }
};

class Solution {
    public int myAtoi(String s) {
        s = s.trim();
        if (s.isEmpty()) return 0;
        int sign = 1;
        int i = 0;
        if (s.charAt(0) == '-') {
            sign = -1; i++;
        } else if (s.charAt(0) == '+') {
            i++;
        }
        int res = 0;
        int maxThreshold = Integer.MAX_VALUE / 10;
        while (i < s.length() && Character.isDigit(s.charAt(i))) {
            int digit = s.charAt(i) - '0';
            if (res > maxThreshold || (res == maxThreshold && digit > 7)) {
                return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            }
            res = res * 10 + digit;
            i++;
        }
        return sign * res;
    }
}

var myAtoi = function(s) {
    s = s.trim();
    if (!s) return 0;
    let sign = 1;
    let i = 0;
    if (s[0] === '-') {
        sign = -1; i++;
    } else if (s[0] === '+') {
        i++;
    }
    let res = 0;
    const INT_MAX = 2147483647;
    const INT_MIN = -2147483648;
    while (i < s.length && s[i] >= '0' && s[i] <= '9') {
        const digit = s.charCodeAt(i) - 48;
        if (res > Math.floor((INT_MAX - digit) / 10)) {
            return sign === 1 ? INT_MAX : INT_MIN;
        }
        res = res * 10 + digit;
        i++;
    }
    return sign * res;
};
